'use client'

// Profil sayfası: avatar yükleme, şifre değiştirme, beslenme/antrenman programı görüntüleme.

import { zodResolver } from '@hookform/resolvers/zod'
import { useRouter } from 'next/navigation'
import type { ChangeEvent, JSX } from 'react'
import { useEffect } from 'react'
import { useForm } from 'react-hook-form'

import {
  useNutritionPlan,
  useProfile,
  useSession,
  useUpdatePassword,
  useUploadAvatar,
  useWorkoutPlan,
} from '@/hooks'
import { QueryState, SkeletonCard, SkeletonText } from '@/components/ui'
import { passwordChangeSchema, type PasswordChangeInput } from '@/lib/validation/schemas'
import {
  DAY_NAMES,
  EMPTY_NUTRITION_PLAN,
  EMPTY_WORKOUT_PLAN,
  type NutritionPlan,
  type WorkoutPlan,
} from '@/types/domain'

/**
 * Antrenman planı görünümü.
 *
 * Faz 1b Adım 2 sonrası kaynak `workout_plans` + `workout_plan_exercises`
 * tablolarıdır; `useWorkoutPlan()` gün->metin sözlüğü döndürür. DEPRECATED
 * `profiles.workout_plan` kolonu artık OKUNMAZ (bayat veri gösteriyordu).
 */
function WorkoutPlanView({ plan }: { plan: WorkoutPlan }): JSX.Element {
  const hasContent = DAY_NAMES.some((day) => plan[day].trim().length > 0)

  if (!hasContent) {
    return (
      <p className="text-sm font-medium leading-relaxed text-gray-700 dark:text-gray-300">
        Koçunuz henüz bir antrenman programı atamadı.
      </p>
    )
  }

  return (
    <ul className="space-y-3">
      {DAY_NAMES.map((day) => (
        <li key={day} className="text-sm">
          <span className="font-bold text-gray-800 dark:text-zinc-200">{day}: </span>
          {/* Bir günün metni birden çok hareket satırı içerebilir ('\n' ile birleşik). */}
          <span className="whitespace-pre-line font-medium text-gray-700 dark:text-gray-300">
            {plan[day].trim() ? plan[day] : '—'}
          </span>
        </li>
      ))}
    </ul>
  )
}

/**
 * Beslenme planı görünümü.
 *
 * Faz 1b Adım 3b sonrası kaynak `nutrition_plans` + `nutrition_plan_meals`
 * tablolarıdır; `useNutritionPlan()` gün->{items,total} sözlüğü döndürür.
 * DEPRECATED `profiles.nutrition_plan` kolonu artık OKUNMAZ (bayat veri
 * gösteriyordu). Kolon JSON string olduğu için burada bir "ayrıştırılamayan ham
 * metin" hâli vardı; tablolar yapılandırılmış veri döndürdüğü için o dal düştü.
 */
function NutritionPlanView({ plan }: { plan: NutritionPlan }): JSX.Element {
  const hasContent = DAY_NAMES.some((day) => plan[day].items.trim().length > 0)

  if (!hasContent) {
    return (
      <p className="text-sm font-medium leading-relaxed text-gray-700 dark:text-gray-300">
        Koçunuz henüz bir beslenme programı atamadı.
      </p>
    )
  }

  return (
    <ul className="space-y-3">
      {DAY_NAMES.map((day) => {
        const entry = plan[day]
        return (
          <li key={day} className="text-sm">
            <span className="font-bold text-gray-800 dark:text-zinc-200">{day}: </span>
            <span className="whitespace-pre-line font-medium text-gray-700 dark:text-gray-300">
              {entry.items.trim() ? `${entry.items} (${entry.total} kcal)` : '—'}
            </span>
          </li>
        )
      })}
    </ul>
  )
}

export default function ProfilePage(): JSX.Element {
  const router = useRouter()

  const { data: session, isLoading: isSessionLoading } = useSession()
  const userId = session?.user.id
  const { data: profile, isLoading: isProfileLoading } = useProfile(userId)
  const workoutPlanQuery = useWorkoutPlan(userId)
  const nutritionPlanQuery = useNutritionPlan(userId)

  const uploadAvatar = useUploadAvatar()
  const updatePassword = useUpdatePassword()

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<PasswordChangeInput>({ resolver: zodResolver(passwordChangeSchema) })

  useEffect(() => {
    if (!isSessionLoading && !session) {
      router.replace('/login')
    }
  }, [isSessionLoading, session, router])

  function handleAvatarUpload(event: ChangeEvent<HTMLInputElement>): void {
    const file = event.target.files?.[0]
    if (!file || !userId) return
    uploadAvatar.mutate({ userId, file })
    event.target.value = ''
  }

  const onSubmitPassword = handleSubmit((values) => {
    updatePassword.mutate(values.password, {
      onSuccess: () => reset(),
    })
  })

  if (isSessionLoading || isProfileLoading || !profile) {
    return (
      <div className="container mx-auto max-w-4xl space-y-8 px-4 py-12">
        <SkeletonCard />
        <div className="grid grid-cols-1 gap-8 md:grid-cols-2">
          <SkeletonText lines={4} />
          <SkeletonText lines={4} />
        </div>
      </div>
    )
  }

  return (
    <main id="main-content" className="container mx-auto max-w-4xl px-4 py-12">
      <button
        onClick={() => router.push('/')}
        className="mb-6 flex items-center gap-2 font-bold text-brand-purple transition-opacity hover:opacity-80"
      >
        ← Ana Sayfaya Dön
      </button>

      <div className="mb-8 flex flex-col items-center gap-8 rounded-3xl border border-gray-100 bg-white p-8 shadow-xl dark:border-zinc-800 dark:bg-[#16161d] md:flex-row md:items-start">
        {/* Avatar Bölümü */}
        <div className="group relative cursor-pointer">
          <div className="flex h-32 w-32 items-center justify-center overflow-hidden rounded-full border-4 border-brand-purple/20 bg-gray-100 transition-all group-hover:border-brand-purple dark:bg-zinc-900">
            {/* Avatar private bucket'tadır: adres imzalıdır ve süreye bağlıdır.
                İmza üretilemezse (dosya yok/erişim yok) kırık görsel yerine 👤 gösterilir. */}
            {profile.avatarSignedUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={profile.avatarSignedUrl}
                alt={`${profile.full_name} profil fotoğrafı`}
                loading="lazy"
                className="h-full w-full object-cover"
              />
            ) : (
              <span className="text-4xl" aria-hidden="true">
                👤
              </span>
            )}
          </div>
          <input
            type="file"
            accept="image/*"
            aria-label="Profil fotoğrafı yükle"
            aria-busy={uploadAvatar.isPending}
            onChange={handleAvatarUpload}
            disabled={uploadAvatar.isPending}
            className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
          />
          {uploadAvatar.isPending && (
            <div
              role="status"
              aria-live="polite"
              className="absolute inset-0 flex items-center justify-center rounded-full bg-black/50 text-xs font-bold text-white"
            >
              Yükleniyor...
            </div>
          )}
        </div>

        {/* Kullanıcı Bilgileri & Şifre */}
        <div className="w-full flex-1 space-y-4">
          <div>
            <h1 className="text-3xl font-black text-gray-800 dark:text-zinc-200">
              {profile.full_name}
            </h1>
            <p className="font-medium text-gray-500">{session?.user.email}</p>
          </div>
          <form
            onSubmit={onSubmitPassword}
            className="flex max-w-md flex-col gap-3 border-t pt-4 dark:border-zinc-800 sm:flex-row"
            noValidate
          >
            <div className="flex-1">
              <label htmlFor="new-password" className="sr-only">
                Yeni Şifre
              </label>
              <input
                id="new-password"
                type="password"
                placeholder="Yeni Şifre Belirle"
                autoComplete="new-password"
                aria-invalid={errors.password ? 'true' : 'false'}
                aria-describedby={errors.password ? 'new-password-error' : undefined}
                className="w-full rounded-xl border bg-gray-50 p-3 text-sm focus:border-brand-purple focus:outline-none dark:border-zinc-800 dark:bg-zinc-950"
                {...register('password')}
              />
              {errors.password && (
                <p
                  id="new-password-error"
                  role="alert"
                  className="mt-1 text-xs font-bold text-red-500"
                >
                  {errors.password.message}
                </p>
              )}
            </div>
            <button
              type="submit"
              disabled={updatePassword.isPending}
              className="h-fit rounded-xl bg-zinc-800 px-6 py-3 text-sm font-bold text-white transition-all hover:bg-black disabled:opacity-50 dark:bg-white dark:text-black dark:hover:bg-gray-200"
            >
              Güncelle
            </button>
          </form>
        </div>
      </div>

      {/* Program Görüntüleme Alanı */}
      <div className="grid grid-cols-1 gap-8 md:grid-cols-2">
        <div className="rounded-3xl border border-gray-100 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-[#16161d]">
          <h3 className="mb-4 border-b pb-3 text-lg font-black text-brand-purple dark:border-zinc-800">
            🥗 Beslenme Programım
          </h3>
          <QueryState
            isLoading={nutritionPlanQuery.isLoading}
            isError={nutritionPlanQuery.isError}
            error={nutritionPlanQuery.error}
            skeleton={<SkeletonText lines={7} />}
            onRetry={() => void nutritionPlanQuery.refetch()}
          >
            <NutritionPlanView plan={nutritionPlanQuery.data ?? EMPTY_NUTRITION_PLAN} />
          </QueryState>
        </div>

        <div className="rounded-3xl border border-gray-100 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-[#16161d]">
          <h3 className="mb-4 border-b pb-3 text-lg font-black text-emerald-500 dark:border-zinc-800">
            🏋️ Antrenman Programım
          </h3>
          <QueryState
            isLoading={workoutPlanQuery.isLoading}
            isError={workoutPlanQuery.isError}
            error={workoutPlanQuery.error}
            skeleton={<SkeletonText lines={7} />}
            onRetry={() => void workoutPlanQuery.refetch()}
          >
            <WorkoutPlanView plan={workoutPlanQuery.data ?? EMPTY_WORKOUT_PLAN} />
          </QueryState>
        </div>
      </div>
    </main>
  )
}

'use client'

// Koç paneli öğrenci portföyü: kart listesi + detay çekmecesi.
//
// Faz 1b sonrası çekmece tamamen ANALİTİK bir görünümdür (kilo trendi, makro
// grafiği, before/after kıyaslama, form hatırlatması). Buradaki ham metin
// program editörleri KALDIRILDI: hem antrenman hem beslenme planı artık kendi
// normalize tablolarında yaşıyor ve yalnızca ilgili sekmelerden yazılıyor;
// bu editörler cutover sonrası DEPRECATED profil kolonlarına yazan "ölü yazma"
// hâline gelmişti (koç kaydediyor, danışan hiç görmüyordu).

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { JSX } from 'react'
import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts'

import { EmptyState, SkeletonCard, SkeletonChart } from '@/components/ui'
import { useDailyLogs, useFormChecks, useLastCheckins, useSendNotification } from '@/hooks'
import type { ProfileWithAvatar } from '@/hooks/useProfile'
import { daysSince, formatDateTR } from '@/lib/utils'

export interface CoachUserManagementProps {
  /** `useProfiles()` çıktısı: profil satırı + avatar için imzalı adres. */
  clients: ProfileWithAvatar[]
}

type WeightPeriod = 'week' | 'month' | 'all'

export function CoachUserManagement({ clients }: CoachUserManagementProps): JSX.Element {
  const [selectedClient, setSelectedClient] = useState<ProfileWithAvatar | null>(null)
  const [isDrawerOpen, setIsDrawerOpen] = useState(false)
  const [weightChartPeriod, setWeightChartPeriod] = useState<WeightPeriod>('month')
  // Kıyaslama seçimleri türetilmiş değer; state yalnızca kullanıcının manuel seçimini (override) tutar.
  const [beforePoseOverride, setBeforePoseOverride] = useState<string | null>(null)
  const [afterPoseOverride, setAfterPoseOverride] = useState<string | null>(null)
  // "Şimdi" render sırasında değil, lazy initializer + event handler'larda hesaplanır (saflık kuralı).
  const [nowMs, setNowMs] = useState<number>(() => Date.now())

  // Prop değişince state'i ayarlamanın resmî React kalıbı: effect yerine render sırasında senkronlama.
  const [prevClientId, setPrevClientId] = useState<string | null>(selectedClient?.id ?? null)
  if ((selectedClient?.id ?? null) !== prevClientId) {
    setPrevClientId(selectedClient?.id ?? null)
    setBeforePoseOverride(null)
    setAfterPoseOverride(null)
  }

  const closeButtonRef = useRef<HTMLButtonElement | null>(null)
  const triggerRef = useRef<HTMLButtonElement | null>(null)
  // Kapanış animasyonu için kurulan setTimeout'un id'si; unmount'ta sızıntı olmaması için tutulur.
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const { data: lastCheckins } = useLastCheckins()
  const formChecksQuery = useFormChecks(selectedClient?.id)
  const dailyLogsQuery = useDailyLogs(selectedClient?.id)
  const sendNotification = useSendNotification()

  const poses = useMemo(() => formChecksQuery.data ?? [], [formChecksQuery.data])

  // Son 14 günlük makro grafiği (sorgu en yeniden eskiye gelir).
  const macroData = useMemo(() => {
    const logs = (dailyLogsQuery.data ?? []).slice(0, 14)
    return logs
      .map((log) => ({
        date: new Date(log.log_date).toLocaleDateString('tr-TR', {
          day: 'numeric',
          month: 'short',
        }),
        Protein: log.macros.protein,
        Karb: log.macros.carb,
        Yag: log.macros.fat,
      }))
      .reverse()
  }, [dailyLogsQuery.data])

  // Varsayılanlar veriden türetilir (en yeni = "after", en eski = "before"); veri yoksa boş.
  const defaultAfterPoseId = poses[0]?.id ?? ''
  const defaultBeforePoseId = poses[poses.length - 1]?.id ?? ''
  const afterPoseId = afterPoseOverride ?? defaultAfterPoseId
  const beforePoseId = beforePoseOverride ?? defaultBeforePoseId

  const closeDrawer = useCallback((): void => {
    setIsDrawerOpen(false)
    triggerRef.current?.focus()
    // Önceki bekleyen timer varsa iptal edilir, unmount'ta da temizlenmesi için ref'te saklanır.
    if (closeTimerRef.current) clearTimeout(closeTimerRef.current)
    closeTimerRef.current = setTimeout(() => setSelectedClient(null), 300)
  }, [])

  // Bileşen unmount olursa bekleyen kapanma timer'ı temizlenir; gövdede setState yok.
  useEffect(() => {
    return () => {
      if (closeTimerRef.current) clearTimeout(closeTimerRef.current)
    }
  }, [])

  // Çekmece açıkken sayfa kaydırması kilitlenir; kapanınca cleanup ile geri alınır.
  useEffect(() => {
    if (!isDrawerOpen) return
    const previous = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.body.style.overflow = previous
    }
  }, [isDrawerOpen])

  useEffect(() => {
    if (!isDrawerOpen) return
    const handleKeyDown = (event: globalThis.KeyboardEvent): void => {
      if (event.key === 'Escape') closeDrawer()
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [isDrawerOpen, closeDrawer])

  useEffect(() => {
    if (isDrawerOpen) closeButtonRef.current?.focus()
  }, [isDrawerOpen])

  const openDrawer = (client: ProfileWithAvatar, trigger: HTMLButtonElement): void => {
    triggerRef.current = trigger
    setSelectedClient(client)
    setIsDrawerOpen(true)
  }

  const sendCheckinReminder = (): void => {
    if (!selectedClient) return
    // Başarı/hata toast'ı hook içinde gösterilir.
    sendNotification.mutate({
      clientIds: [selectedClient.id],
      title: '⚠️ Check-in Zamanı!',
      message:
        'Koçunuz güncel formunuzu bekliyor. Lütfen kilonuzu ve form fotoğraflarınızı sisteme yükleyin.',
    })
  }

  /** 7 günden eskiyse veya hiç form yoksa kırmızı. */
  const isCheckinLate = (clientId: string): boolean => {
    const lastDate = lastCheckins?.[clientId]
    if (!lastDate) return true
    // Render saf kalsın diye "şimdi" argümanı Date.now() yerine state'teki `nowMs`'ten üretilir.
    return daysSince(lastDate, new Date(nowMs)) > 7
  }

  const filteredWeightData = useMemo(() => {
    if (poses.length === 0) return []

    // Render saf kalsın diye Date.now() yerine state'teki `nowMs` kullanılır.
    let cutoff = new Date(0)
    if (weightChartPeriod === 'week') cutoff = new Date(nowMs - 7 * 86_400_000)
    else if (weightChartPeriod === 'month') cutoff = new Date(nowMs - 30 * 86_400_000)

    return poses
      .filter((pose) => new Date(pose.created_at) >= cutoff)
      .map((pose) => ({
        date: new Date(pose.created_at).toLocaleDateString('tr-TR', {
          day: 'numeric',
          month: 'short',
        }),
        kilo: pose.current_weight,
      }))
      .reverse()
  }, [poses, weightChartPeriod, nowMs])

  const firstWeight = filteredWeightData[0]
  const lastWeight = filteredWeightData[filteredWeightData.length - 1]
  const weightSummary =
    firstWeight && lastWeight
      ? `İlk kayıt ${firstWeight.kilo} kg, son kayıt ${lastWeight.kilo} kg, net değişim ${(
          lastWeight.kilo - firstWeight.kilo
        ).toFixed(1)} kg.`
      : ''

  const beforePose = poses.find((p) => p.id === beforePoseId)
  const afterPose = poses.find((p) => p.id === afterPoseId)
  const clientCards = clients.filter((c) => c.role !== 'coach')
  const isLoading = formChecksQuery.isLoading || dailyLogsQuery.isLoading

  return (
    <div>
      <h3 className="mb-6 text-xl font-black text-gray-800 dark:text-zinc-200">Öğrenci Portföyü</h3>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 md:grid-cols-3">
        {clientCards.map((client) => {
          const late = isCheckinLate(client.id)
          return (
            <button
              type="button"
              key={client.id}
              onClick={(event) => {
                // Drawer açılırken filtre eşiği bayatlamasın diye "şimdi" tazelenir.
                // Bu çağrı satır içi event handler'da olmalı; bileşen gövdesindeki bir
                // fonksiyona taşınırsa react-hooks/purity kuralı render kapsamı sayar.
                setNowMs(Date.now())
                openDrawer(client, event.currentTarget)
              }}
              className="group relative w-full cursor-pointer rounded-2xl border border-gray-100 bg-white p-5 text-left shadow-sm transition-all hover:border-brand-purple dark:border-zinc-800 dark:bg-[#16161d] dark:hover:border-brand-purple"
            >
              {/* Durum yalnızca renkle anlatılmasın diye metin karşılığı sr-only olarak eklenir. */}
              <span
                aria-hidden="true"
                className={`absolute right-4 top-4 h-3 w-3 animate-pulse rounded-full shadow-sm ${
                  late ? 'bg-red-500' : 'bg-emerald-500'
                }`}
              />
              <span className="sr-only">{late ? 'Form gecikti' : 'Form güncel'}</span>

              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center overflow-hidden rounded-full border border-brand-purple/20 bg-brand-purple/10 text-lg font-black text-brand-purple">
                  {/* Private bucket: imzalı adres yoksa baş harf gösterilir (kırık görsel yok). */}
                  {client.avatarSignedUrl ? (
                    <img
                      src={client.avatarSignedUrl}
                      alt=""
                      loading="lazy"
                      className="h-full w-full object-cover"
                    />
                  ) : (
                    (client.full_name ?? '?').charAt(0).toUpperCase()
                  )}
                </div>
                <div>
                  <h4 className="font-bold text-gray-800 transition-colors group-hover:text-brand-purple dark:text-zinc-200">
                    {client.full_name}
                  </h4>
                  <p className="text-xs text-gray-500">{client.email}</p>
                </div>
              </div>
            </button>
          )
        })}
      </div>

      {/* --- SLIDE-OVER DRAWER --- */}
      <div
        className={`fixed inset-0 z-50 transition-opacity duration-300 ${
          isDrawerOpen ? 'pointer-events-auto opacity-100' : 'pointer-events-none opacity-0'
        }`}
      >
        <div
          className="absolute inset-0 bg-black/40 backdrop-blur-sm"
          onClick={closeDrawer}
          aria-hidden="true"
        />

        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="client-drawer-title"
          className={`absolute right-0 top-0 h-full w-full max-w-2xl transform overflow-y-auto border-l border-zinc-200 bg-slate-50 shadow-2xl transition-transform duration-300 ease-in-out dark:border-zinc-800 dark:bg-[#0f0f12] ${
            isDrawerOpen ? 'translate-x-0' : 'translate-x-full'
          }`}
        >
          {selectedClient && (
            <div className="space-y-8 p-6 pb-24 md:p-8">
              <div className="flex items-center justify-between border-b pb-4 dark:border-zinc-800">
                <div>
                  <h2
                    id="client-drawer-title"
                    className="bg-gradient-to-r from-brand-purple to-purple-500 bg-clip-text text-2xl font-black text-transparent"
                  >
                    {selectedClient.full_name}
                  </h2>
                  <button
                    type="button"
                    onClick={sendCheckinReminder}
                    disabled={sendNotification.isPending}
                    className="mt-2 flex items-center gap-1 rounded-lg bg-red-500 px-3 py-1.5 text-xs font-bold text-white shadow-sm transition-all hover:bg-red-600 disabled:opacity-50"
                  >
                    <span aria-hidden="true">🔔</span> Form Hatırlatması Gönder
                  </button>
                </div>
                <button
                  type="button"
                  ref={closeButtonRef}
                  onClick={closeDrawer}
                  aria-label="Öğrenci detayını kapat"
                  className="flex h-10 w-10 items-center justify-center rounded-full bg-gray-200 font-bold text-gray-600 transition-all hover:bg-red-500 hover:text-white dark:bg-zinc-800 dark:text-gray-400"
                >
                  <span aria-hidden="true">✕</span>
                </button>
              </div>

              {isLoading ? (
                <div className="flex flex-col gap-6">
                  <SkeletonChart />
                  <SkeletonCard />
                </div>
              ) : (
                <>
                  <div className="rounded-3xl border border-gray-100 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-[#16161d]">
                    <div className="mb-6 flex items-center justify-between">
                      <h3 className="text-sm font-bold uppercase tracking-wider text-gray-500">
                        Kilo Değişim Trendi
                      </h3>
                      <div className="flex rounded-lg bg-gray-100 p-1 dark:bg-zinc-900">
                        <button
                          type="button"
                          onClick={() => {
                            // "Şimdi" event handler'da tazelenir; render saf kalır.
                            setWeightChartPeriod('week')
                            setNowMs(Date.now())
                          }}
                          aria-pressed={weightChartPeriod === 'week'}
                          className={`rounded-md px-3 py-1 text-xs font-bold ${
                            weightChartPeriod === 'week'
                              ? 'bg-white text-brand-purple dark:bg-zinc-700'
                              : 'text-gray-500'
                          }`}
                        >
                          1 Hafta
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            setWeightChartPeriod('month')
                            setNowMs(Date.now())
                          }}
                          aria-pressed={weightChartPeriod === 'month'}
