          )}
        </div>
      </div>
    </div>
  )
}

'use client'

// Panelin sekme kabuğu: koç için öğrenci seçimi/arama, öğrenci için streak başlığı
// ve seçili sekmenin içeriğini render eder.

import { useRef, useState } from 'react'
import type { JSX, KeyboardEvent } from 'react'
import { toast } from 'sonner'

import { useNotifications, useProfile } from '@/hooks'
import type { Profile, UserRole } from '@/types'

import AnnouncementsTab from './tabs/AnnouncementsTab'
import DailyLogTab from './tabs/DailyLogTab'
import FormCheckTab from './tabs/FormCheckTab'
import MessagesTab from './tabs/MessagesTab'
import NutritionTab from './tabs/NutritionTab'
import StatsTab from './tabs/StatsTab'
import WorkoutTab from './tabs/WorkoutTab'

export interface DashboardTabsProps {
  currentUserId: string | undefined
  userRole: UserRole | null | undefined
  clients: Profile[]
}

const TABS = [
  'announcements',
  'stats',
  'formCheck',
  'daily',
  'nutrition',
  'workout',
  'messages',
] as const

type TabKey = (typeof TABS)[number]

const ITEMS_PER_PAGE = 5

export function DashboardTabs({
  currentUserId,
  userRole,
  clients,
}: DashboardTabsProps): JSX.Element {
  const [activeTab, setActiveTab] = useState<TabKey>('formCheck')
  const exportRef = useRef<HTMLDivElement | null>(null)
  const tabRefs = useRef<Partial<Record<TabKey, HTMLButtonElement | null>>>({})

  const [searchTerm, setSearchTerm] = useState('')
  const [selectedClientIds, setSelectedClientIds] = useState<string[]>([])
  const [currentPage, setCurrentPage] = useState(0)

  const clientsList = clients.filter((c) => c.role !== 'coach')
  const filteredClients = clientsList.filter((c) =>
    (c.full_name ?? '').toLowerCase().includes(searchTerm.toLowerCase())
  )
  const totalPages = Math.ceil(filteredClients.length / ITEMS_PER_PAGE)
  const safeTotalPages = Math.max(totalPages, 1)
  const criticalClients = clientsList.filter((c) => c.current_streak === 0)

  const targetId =
    userRole === 'coach'
      ? selectedClientIds.length === 1
        ? selectedClientIds[0]
        : undefined
      : currentUserId

  const { data: profile } = useProfile(targetId)
  const currentStreak = profile?.current_streak ?? 0

  const { data: announcementData } = useNotifications(targetId, { sinceDays: 30 })
  const announcements = announcementData ?? []

  const handleDownloadImage = async (): Promise<void> => {
    if (!exportRef.current) return
    try {
      // Dinamik import: 1.4MB'lık paket ilk yüklemede bundle'a girmesin.
      const { default: html2canvas } = await import('html2canvas')
      const canvas = await html2canvas(exportRef.current, { backgroundColor: null, scale: 2 })
      const link = document.createElement('a')
      link.href = canvas.toDataURL('image/png')
      link.download = `kocluk_${activeTab}.png`
      link.click()
    } catch {
      toast.error('Görsel oluşturulamadı. Lütfen tekrar deneyin.')
    }
  }

  const toggleClient = (id: string): void =>
    setSelectedClientIds((prev) =>
      prev.includes(id) ? prev.filter((cId) => cId !== id) : [...prev, id]
    )

  const selectAll = (): void =>
    setSelectedClientIds(
      selectedClientIds.length === filteredClients.length ? [] : filteredClients.map((c) => c.id)
    )

  const nextBtn = (): void => setCurrentPage((p) => Math.min(totalPages - 1, p + 1))
  const prevBtn = (): void => setCurrentPage((p) => Math.max(0, p - 1))

  const focusTab = (tab: TabKey): void => {
    setActiveTab(tab)
    tabRefs.current[tab]?.focus()
  }

  const handleTabKeyDown = (event: KeyboardEvent<HTMLDivElement>): void => {
    const index = TABS.indexOf(activeTab)
    if (index < 0) return

    if (event.key === 'ArrowRight') {
      event.preventDefault()
      focusTab(TABS[(index + 1) % TABS.length] as TabKey)
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      focusTab(TABS[(index - 1 + TABS.length) % TABS.length] as TabKey)
    } else if (event.key === 'Home') {
      event.preventDefault()
      focusTab(TABS[0])
    } else if (event.key === 'End') {
      event.preventDefault()
      focusTab(TABS[TABS.length - 1] as TabKey)
    }
  }

  const tabProps = {
    targetId,
    currentUserId,
    userRole,
    selectedClientIds,
    onDownloadImage: () => void handleDownloadImage(),
  }

  return (
    <div className="mt-4 w-full">
      {/* Öğrenci Başlığı (Streak) */}
      {userRole === 'client' && (
        <div className="mb-6 flex items-center justify-between rounded-2xl border border-orange-500/20 bg-gradient-to-r from-orange-500/10 to-transparent p-4">
          <div>
            <h3 className="text-sm font-black text-orange-600 dark:text-orange-400">
              <span aria-hidden="true">🔥</span> GÜNLÜK SERİ (STREAK)
            </h3>
            <p className="text-xs text-gray-600 dark:text-gray-300">
              Raporları aksatmadan ilerliyorsun, bozma!
            </p>
          </div>
          <div className="animate-pulse text-3xl font-black text-orange-500 drop-shadow-md">
            {currentStreak} GÜN
          </div>
        </div>
      )}

      {/* Koç Öğrenci Paneli */}
      {userRole === 'coach' && (
        <>
          {criticalClients.length > 0 && (
            <div className="mb-6 rounded-2xl border border-red-200 bg-red-50 p-4 dark:border-red-900/30 dark:bg-red-900/10">
              <h3 className="mb-3 flex items-center gap-2 text-xs font-black uppercase tracking-widest text-red-600 dark:text-red-400">
                <span className="h-2 w-2 animate-ping rounded-full bg-red-500" aria-hidden="true" />{' '}
                Acil İlgilenilmesi Gerekenler
              </h3>
              <div className="hide-scrollbar flex gap-3 overflow-x-auto">
                {criticalClients.map((c) => (
                  <button
                    type="button"
                    key={c.id}
                    onClick={() => toggleClient(c.id)}
                    aria-pressed={selectedClientIds.includes(c.id)}
                    aria-label={`${c.full_name ?? 'Öğrenci'} seç`}
                    className="cursor-pointer whitespace-nowrap rounded-xl border border-red-100 bg-white px-3 py-2 text-xs font-bold text-gray-700 shadow-sm transition-transform hover:scale-105 dark:border-red-900/20 dark:bg-[#16161d] dark:text-gray-300"
                  >
                    <span aria-hidden="true">⚠️</span> {(c.full_name ?? '').split(' ')[0] ?? ''}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="mb-8 overflow-hidden rounded-3xl border border-gray-200 bg-white p-5 shadow-sm transition-all dark:border-zinc-800 dark:bg-[#16161d]">
            <div className="mb-6 flex flex-col items-start justify-between gap-4 border-b border-gray-100 pb-4 dark:border-zinc-800 md:flex-row md:items-center">
              <div>
                <h3 className="text-sm font-black uppercase tracking-widest text-brand-purple">
                  Öğrenci Yönetimi
                </h3>
              </div>
              <div className="relative w-full md:w-64">
                <span
                  className="absolute inset-y-0 left-3 flex items-center text-sm text-gray-400"
                  aria-hidden="true"
                >
                  🔍
                </span>
                <label htmlFor="client-search" className="sr-only">
                  Öğrenci Ara
                </label>
                <input
                  id="client-search"
                  type="text"
                  placeholder="Öğrenci Ara..."
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value)
                    setCurrentPage(0)
                  }}
                  className="w-full rounded-xl border border-gray-200 bg-gray-50 py-2.5 pl-9 pr-3 text-sm transition-all focus:border-brand-purple focus:outline-none dark:border-zinc-700 dark:bg-zinc-900"
                />
              </div>
              <div className="flex w-full items-center justify-between gap-4 md:w-auto">
                <button
                  type="button"
                  onClick={selectAll}
                  className="whitespace-nowrap rounded-lg bg-gray-100 px-3 py-1.5 text-xs font-bold text-gray-600 transition-all hover:bg-brand-purple hover:text-white dark:bg-zinc-800 dark:text-gray-300"
                >
                  {selectedClientIds.length === filteredClients.length && filteredClients.length > 0
                    ? 'SEÇİMİ TEMİZLE'
                    : 'TÜMÜNÜ SEÇ'}
                </button>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={prevBtn}
                    disabled={currentPage === 0}
                    aria-label="Önceki sayfa"
                    className="flex h-8 w-8 items-center justify-center rounded-full bg-gray-100 transition-all hover:bg-brand-purple hover:text-white disabled:opacity-30 dark:bg-zinc-800"
                  >
                    <span aria-hidden="true">{'<'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={nextBtn}
                    disabled={currentPage >= totalPages - 1 || totalPages === 0}
                    aria-label="Sonraki sayfa"
                    className="flex h-8 w-8 items-center justify-center rounded-full bg-gray-100 transition-all hover:bg-brand-purple hover:text-white disabled:opacity-30 dark:bg-zinc-800"
                  >
                    <span aria-hidden="true">{'>'}</span>
                  </button>
                </div>
              </div>
            </div>

            <div className="relative h-24 w-full overflow-hidden">
              {filteredClients.length === 0 ? (
                <div className="flex h-full items-center justify-center text-xs font-bold text-gray-400">
                  Aramayla eşleşen öğrenci bulunamadı.
                </div>
              ) : (
                <div
                  className="absolute left-0 top-0 flex h-full transition-transform duration-500 ease-out"
                  style={{
                    transform: `translateX(-${currentPage * 100}%)`,
                    width: `${safeTotalPages * 100}%`,
                  }}
                >
                  {Array.from({ length: safeTotalPages }).map((_, pageIndex) => (
                    <div
                      key={pageIndex}
                      className="flex justify-around gap-4 px-2"
                      style={{ width: `${100 / safeTotalPages}%` }}
                    >
                      {filteredClients
                        .slice(pageIndex * ITEMS_PER_PAGE, (pageIndex + 1) * ITEMS_PER_PAGE)
                        .map((client) => {
                          const isSelected = selectedClientIds.includes(client.id)
                          const fullName = client.full_name ?? ''
                          const firstName = fullName.split(' ')[0] ?? ''
                          return (
                            <button
                              type="button"
                              key={client.id}
                              onClick={() => toggleClient(client.id)}
                              aria-pressed={isSelected}
                              aria-label={`${fullName || 'Öğrenci'} seç`}
                              className="group relative flex w-16 cursor-pointer flex-col items-center gap-2"
                            >
                              <div className="relative">
                                <img
                                  src={`https://ui-avatars.com/api/?name=${encodeURIComponent(
                                    fullName
                                  )}&background=random&color=fff&bold=true`}
                                  alt=""
                                  loading="lazy"
                                  className={`h-14 w-14 rounded-full object-cover shadow-sm transition-all duration-300 ${
                                    isSelected
                                      ? 'scale-110 ring-4 ring-brand-purple'
                                      : 'opacity-60 grayscale hover:grayscale-0 group-hover:scale-105 group-hover:opacity-100'
                                  }`}
                                />
                                {client.current_streak > 0 && (
                                  <span className="absolute -bottom-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full border-2 border-white bg-orange-500 text-[9px] font-black text-white dark:border-zinc-900">
                                    {client.current_streak}
                                  </span>
                                )}
                              </div>
                              <span
                                className={`w-full truncate text-center text-[10px] font-bold ${
                                  isSelected ? 'text-brand-purple' : 'text-gray-500'
                                }`}
                              >
                                {firstName}
                              </span>
                            </button>
                          )
                        })}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </>
      )}

      {/* SEKMELER MENÜSÜ */}
      <div
        role="tablist"
        aria-label="Panel sekmeleri"
        onKeyDown={handleTabKeyDown}
        className="hide-scrollbar flex gap-6 overflow-x-auto border-b border-gray-200 pb-2 text-sm font-medium dark:border-zinc-800"
      >
        {TABS.map((tab) => (
          <button
            type="button"
            key={tab}
            id={`tab-${tab}`}
            role="tab"
            aria-selected={activeTab === tab}
            aria-controls={`panel-${tab}`}
            tabIndex={activeTab === tab ? 0 : -1}
            ref={(el) => {
              tabRefs.current[tab] = el
            }}
            onClick={() => setActiveTab(tab)}
            className={`relative flex items-center gap-2 whitespace-nowrap pb-2 transition-all ${
              activeTab === tab
                ? 'font-bold text-brand-purple'
                : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'
            }`}
          >
            {tab === 'announcements' && (
              <>
                <span aria-hidden="true">🔔</span> Duyurular{' '}
                {announcements.length > 0 && (
                  <span className="animate-bounce rounded-full bg-red-500 px-2 py-0.5 text-[10px] text-white">
                    {announcements.length}
                  </span>
                )}
              </>
            )}
            {tab === 'stats' && (
              <>
                <span aria-hidden="true">📈</span> İstatistikler
              </>
            )}
            {tab === 'formCheck' && (
              <>
                <span aria-hidden="true">📸</span> Form Check
              </>
            )}
            {tab === 'daily' && (
              <>
                <span aria-hidden="true">📊</span> Günlük Veriler
              </>
            )}
            {tab === 'nutrition' && (
              <>
                <span aria-hidden="true">🥗</span> Beslenme
              </>
            )}
            {tab === 'workout' && (
              <>
                <span aria-hidden="true">🏋️</span> Antrenman
              </>
            )}
            {tab === 'messages' && (
              <>
                <span aria-hidden="true">💬</span> Sohbet
              </>
            )}
            {activeTab === tab && (
              <span
                aria-hidden="true"
                className="absolute bottom-[-9px] left-0 h-[2px] w-full bg-brand-purple shadow-[0_0_8px_rgba(139,92,246,0.8)]"
              />
            )}
          </button>
        ))}
      </div>

      {/* RENDER EDİLEN AKTİF SEKME İÇERİĞİ */}
      <div
        ref={exportRef}
        role="tabpanel"
        id={`panel-${activeTab}`}
        aria-labelledby={`tab-${activeTab}`}
        tabIndex={0}
        className="mt-4 min-h-[400px] rounded-3xl border border-gray-100 bg-white p-5 shadow-sm dark:border-zinc-800 dark:bg-[#16161d] md:p-8"
      >
        {userRole === 'coach' && selectedClientIds.length === 0 ? (
          <div className="flex h-64 flex-col items-center justify-center text-sm font-bold text-gray-500">
            <span className="mb-3 text-4xl opacity-50" aria-hidden="true">
              👥
            </span>
            Lütfen yukarıdaki panelden en az bir öğrenci seçin.
          </div>
        ) : (
          <>
            {activeTab === 'stats' && (
              <StatsTab
                targetId={targetId}
                userRole={userRole}
                selectedClientIds={selectedClientIds}
              />
            )}
            {activeTab === 'announcements' && (
              <AnnouncementsTab
                announcements={announcements}
                userRole={userRole}
                selectedClientIds={selectedClientIds}
              />
            )}
            {activeTab === 'formCheck' && (
              <FormCheckTab
                targetId={tabProps.targetId}
                currentUserId={tabProps.currentUserId}
                userRole={tabProps.userRole}
                selectedClientIds={tabProps.selectedClientIds}
              />
            )}
            {activeTab === 'daily' && (
              <DailyLogTab
                targetId={tabProps.targetId}
                currentUserId={tabProps.currentUserId}
                userRole={tabProps.userRole}
                selectedClientIds={tabProps.selectedClientIds}
              />
            )}
            {activeTab === 'nutrition' && (
              <NutritionTab
                targetId={tabProps.targetId}
                currentUserId={tabProps.currentUserId}
                userRole={tabProps.userRole}
                selectedClientIds={tabProps.selectedClientIds}
                onDownloadImage={tabProps.onDownloadImage}
              />
            )}
            {activeTab === 'workout' && (
              <WorkoutTab
                targetId={tabProps.targetId}
                currentUserId={tabProps.currentUserId}
                userRole={tabProps.userRole}
                selectedClientIds={tabProps.selectedClientIds}
                onDownloadImage={tabProps.onDownloadImage}
              />
            )}
            {activeTab === 'messages' && (
              <MessagesTab
                targetId={tabProps.targetId}
                currentUserId={tabProps.currentUserId}
                userRole={tabProps.userRole}
                selectedClientIds={tabProps.selectedClientIds}
              />
            )}
          </>
        )}
      </div>
    </div>
  )
}

'use client'

// Haftalık beslenme planı: AI diyetisyen, oto-tamamlamalı hızlı besin ekleme
// ve gün bazlı otomatik kalori hesabı. Plan `nutrition_plans` / `nutrition_plan_meals`
// tablolarında saklanır; `useNutritionPlan` üzerinden okunur/yazılır.

import { zodResolver } from '@hookform/resolvers/zod'
import { useMemo, useState } from 'react'
import type { JSX, KeyboardEvent } from 'react'
import { useForm } from 'react-hook-form'
import { toast } from 'sonner'

import { QueryState, SkeletonTable } from '@/components/ui'
import { useFoods, useGenerateDiet, useNutritionPlan, useSaveNutritionPlan } from '@/hooks'
import { DAYS, downloadCSV } from '@/lib/utils'
import { aiDietSchema, type AiDietInput } from '@/lib/validation/schemas'
import { DAY_NAMES, type DayName, type FoodItem, type NutritionPlan, type UserRole } from '@/types'

export interface NutritionTabProps {
  targetId: string | undefined
  currentUserId: string | undefined
  userRole: UserRole | null | undefined
  selectedClientIds: string[]
  onDownloadImage: () => void
}

function emptyPlan(): NutritionPlan {
  const plan = {} as NutritionPlan
  for (const day of DAY_NAMES) plan[day] = { items: '', total: 0 }
  return plan
}

/** Tek bir günü değiştirip yeni plan nesnesi döndürür (tip güvenli kopya). */
function withDay(plan: NutritionPlan, day: DayName, items: string, total: number): NutritionPlan {
  const next: NutritionPlan = { ...plan }
  next[day] = { items, total }
  return next
}

export default function NutritionTab({
  targetId,
  currentUserId,
  userRole,
  selectedClientIds,
  onDownloadImage,
}: NutritionTabProps): JSX.Element {
  const foodsQuery = useFoods()
  const planQuery = useNutritionPlan(targetId)
  const savePlan = useSaveNutritionPlan()
  const generateDiet = useGenerateDiet()

  const foodDB: FoodItem[] = useMemo(() => foodsQuery.data ?? [], [foodsQuery.data])

  const [nutritionData, setNutritionData] = useState<NutritionPlan>(() => emptyPlan())
  const [targetCalories, setTargetCalories] = useState(0)

  // targetId değiştiğinde düzenleme taslağını sunucudan gelen planla tazeler.
  // React'in "prop değişince state ayarlama" kalıbı: render sırasında setState,
  // effect kullanmadan — böylece cascading render oluşmaz ve set-state-in-effect
  // lint hatası ortadan kalkar. Anahtar yalnızca targetId değil, "targetId + planın
  // yüklenmiş olması" — planQuery.data asenkron geldiği için targetId değişir değişmez
  // henüz undefined olabilir; veri gelince taslağı yükleyebilmek için isFetched de anahtara girer.
  // Aynı öğrenci için anahtar sabit kaldığı sürece (ör. arka planda refetch) kullanıcının
  // düzenlemeleri ezilmez.
  const planKey = targetId ? `${targetId}:${planQuery.isFetched ? '1' : '0'}` : 'none'
  const [loadedPlanKey, setLoadedPlanKey] = useState(planKey)
  if (planKey !== loadedPlanKey) {
    setLoadedPlanKey(planKey)
    setNutritionData(
      targetId && planQuery.isFetched ? (planQuery.data ?? emptyPlan()) : emptyPlan()
    )
  }

  // --- Hızlı besin ekleme (combobox) -----------------------------------------
  const [quickAddDay, setQuickAddDay] = useState<DayName>(DAY_NAMES[0])
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedFood, setSelectedFood] = useState<FoodItem | null>(null)
  const [quickAddGrams, setQuickAddGrams] = useState('100')
  const [activeIndex, setActiveIndex] = useState(-1)

  const suggestions = useMemo(() => {
    if (searchQuery.trim().length <= 1 || selectedFood) return []
    const q = searchQuery.toLowerCase()
    return foodDB.filter((f) => f.name.toLowerCase().includes(q)).slice(0, 5)
  }, [searchQuery, selectedFood, foodDB])

  const isListOpen = suggestions.length > 0
  const activeOption = activeIndex >= 0 ? suggestions[activeIndex] : undefined

  const calculateCalories = (foodName: string, grams: number): number => {
    const food = foodDB.find((f) => f.name.toLowerCase() === foodName.toLowerCase().trim())
    if (!food) return 0
    return Math.round((food.calories_per_100g * grams) / 100)
  }

  /** "Yulaf:80, Tavuk:200" biçimindeki listenin toplam kalorisini hesaplar. */
  const sumCalories = (itemsString: string): number => {
    let total = 0
    for (const item of itemsString.split(',')) {
      const parts = item.split(':')
      if (parts.length !== 2) continue
      const name = parts[0]
      const grams = parts[1]
      if (name === undefined || grams === undefined) continue
      total += calculateCalories(name, Number.parseInt(grams, 10) || 0)
    }
    return total
  }

  const pickFood = (food: FoodItem): void => {
    setSelectedFood(food)
    setSearchQuery(food.name)
    setActiveIndex(-1)
  }

  const handleSearchKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
    if (!isListOpen) return

    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setActiveIndex((prev) => (prev + 1) % suggestions.length)
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      setActiveIndex((prev) => (prev <= 0 ? suggestions.length - 1 : prev - 1))
    } else if (event.key === 'Enter') {
      const candidate = activeIndex >= 0 ? suggestions[activeIndex] : suggestions[0]
      if (candidate) {
        event.preventDefault()
        pickFood(candidate)
      }
    } else if (event.key === 'Escape') {
      event.preventDefault()
      setActiveIndex(-1)
      setSearchQuery('')
    }
  }

  const handleQuickAdd = (): void => {
    if (!selectedFood) {
      toast.error('Lütfen listeden bir besin seçin.')
      return
    }
    const grams = Number.parseInt(quickAddGrams, 10)
    if (!Number.isFinite(grams) || grams <= 0) {
      toast.error('Geçerli bir gramaj girin.')
      return
    }

    const newEntry = `${selectedFood.name}:${grams}`
    const current = nutritionData[quickAddDay]
    const newItemsString = current.items ? `${current.items}, ${newEntry}` : newEntry

    setNutritionData((prev) =>
      withDay(prev, quickAddDay, newItemsString, sumCalories(newItemsString))
    )
    setSearchQuery('')
    setSelectedFood(null)
    setQuickAddGrams('100')
    setActiveIndex(-1)
  }

  const handleManualNutritionChange = (day: DayName, value: string): void => {
    setNutritionData((prev) => withDay(prev, day, value, sumCalories(value)))
  }

  // --- AI diyetisyen ----------------------------------------------------------
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<AiDietInput>({
    resolver: zodResolver(aiDietSchema),
    defaultValues: {
      age: 20,
      height_cm: 175,
      weight_kg: 70,
      gender: 'male',
      steps: 6500,
      goal: 'maintain',
      user_prompt: '',
    },
  })

  const onGenerate = handleSubmit(async (values) => {
    // İstek Next.js proxy route'una gider; hata mesajları hook/proxy tarafından verilir.
    const result = await generateDiet.mutateAsync(values)

    setTargetCalories(result.target_calories)

    const next = emptyPlan()
    for (const day of DAY_NAMES) {
      const itemsString = result.diet_plan[day] ?? ''
      next[day] = { items: itemsString, total: sumCalories(itemsString) }
    }
    setNutritionData(next)
  })

  // --- Kaydetme ---------------------------------------------------------------
  const handleSaveProgram = (): void => {
    const clientIds =
      userRole === 'coach' ? selectedClientIds : currentUserId ? [currentUserId] : []
    if (clientIds.length === 0) {
      toast.error('Öğrenci seçin!')
      return
    }
    // Başarı/hata toast'ı hook içinde gösterilir.
    savePlan.mutate({ clientIds, plan: nutritionData })
  }

  const handleDownloadCsv = (): void => {
    // Mevcut davranış korunur: her gün ayrı bir sütun olarak tek satırda dışa aktarılır.
    const row = Object.fromEntries(DAY_NAMES.map((day) => [day, nutritionData[day]] as const))
    downloadCSV([row], 'Beslenme_Programi', false)
  }

  const isGenerating = generateDiet.isPending

  return (
    <div className="animate-fadeIn space-y-6">
      <div className="flex items-center justify-between border-b pb-3 dark:border-zinc-800">
        <h4 className="text-lg font-bold text-gray-800 dark:text-zinc-200">
          Haftalık Beslenme Planı
        </h4>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={onDownloadImage}
            className="rounded-lg bg-brand-purple/10 px-3 py-1.5 text-xs font-bold text-brand-purple"
          >
            <span aria-hidden="true">🖼️</span> Görsel İndir
          </button>
          <button
            type="button"
            onClick={handleDownloadCsv}
            className="rounded-lg bg-emerald-500/10 px-3 py-1.5 text-xs font-bold text-emerald-600"
          >
            <span aria-hidden="true">📊</span> CSV İndir
          </button>
        </div>
      </div>

      {/* AKILLI DİYETİSYEN PANELİ */}
      <form
        onSubmit={onGenerate}
        noValidate
        className="mb-6 rounded-2xl border border-brand-purple/20 bg-gradient-to-br from-brand-purple/5 to-transparent p-5 shadow-inner"
      >
        <h4 className="mb-4 flex items-center gap-2 text-sm font-black text-brand-purple">
          <span aria-hidden="true">🧠</span> AI DİYETİSYEN &amp; KALORİ HESAPLAYICI
        </h4>
        <div className="flex flex-col gap-6 md:flex-row">
          <div className="grid flex-1 grid-cols-2 gap-3 md:grid-cols-3">
            <div>
              <label htmlFor="ai-diet-age" className="sr-only">
                Yaş
              </label>
              <input
                id="ai-diet-age"
                type="number"
                placeholder="Yaş"
                {...register('age')}
                aria-invalid={errors.age ? 'true' : 'false'}
                className="w-full rounded-xl border bg-white p-3 text-xs outline-none focus:border-brand-purple dark:bg-zinc-900"
              />
              {errors.age ? (
                <p role="alert" className="mt-1 text-[10px] font-bold text-red-500">
                  {errors.age.message}
                </p>
              ) : null}
            </div>
            <div>
              <label htmlFor="ai-diet-height" className="sr-only">
                Boy (cm)
              </label>
              <input
                id="ai-diet-height"
                type="number"
                placeholder="Boy (cm)"
                {...register('height_cm')}
                aria-invalid={errors.height_cm ? 'true' : 'false'}
                className="w-full rounded-xl border bg-white p-3 text-xs outline-none focus:border-brand-purple dark:bg-zinc-900"
              />
              {errors.height_cm ? (
                <p role="alert" className="mt-1 text-[10px] font-bold text-red-500">
                  {errors.height_cm.message}
                </p>
              ) : null}
            </div>
            <div>
              <label htmlFor="ai-diet-weight" className="sr-only">
                Kilo (kg)
              </label>
              <input
                id="ai-diet-weight"
                type="number"
                placeholder="Kilo (kg)"
                {...register('weight_kg')}
                aria-invalid={errors.weight_kg ? 'true' : 'false'}
                className="w-full rounded-xl border bg-white p-3 text-xs outline-none focus:border-brand-purple dark:bg-zinc-900"
              />
              {errors.weight_kg ? (
                <p role="alert" className="mt-1 text-[10px] font-bold text-red-500">
                  {errors.weight_kg.message}
                </p>
              ) : null}
            </div>
            <div>
              <label htmlFor="ai-diet-gender" className="sr-only">
                Cinsiyet
              </label>
              <select
                id="ai-diet-gender"
                {...register('gender')}
                className="w-full rounded-xl border bg-white p-3 text-xs outline-none focus:border-brand-purple dark:bg-zinc-900"
              >
                <option value="male">Erkek</option>
                <option value="female">Kadın</option>
              </select>
            </div>
            <div>
              <label htmlFor="ai-diet-steps" className="sr-only">
                Günlük adım sayısı
              </label>
              <select
                id="ai-diet-steps"
                {...register('steps')}
                className="w-full rounded-xl border bg-white p-3 text-xs outline-none focus:border-brand-purple dark:bg-zinc-900"
              >
                <option value={4000}>&lt; 5.000 Adım (Masa Başı)</option>
                <option value={6500}>5.000 - 8.000 Adım</option>
                <option value={9000}>8.000 - 10.000 Adım</option>
                <option value={11000}>10.000 - 12.000 Adım</option>
                <option value={13000}>12.000+ Adım (Çok Hareketli)</option>
              </select>
            </div>
            <div>
              <label htmlFor="ai-diet-goal" className="sr-only">
                Hedef
              </label>
              <select
                id="ai-diet-goal"
                {...register('goal')}
                className="w-full rounded-xl border bg-orange-50 p-3 text-xs font-bold text-orange-600 outline-none focus:border-orange-500 dark:bg-orange-900/20"
              >
                <option value="maintain">Koruma (0 kcal)</option>
                <option value="cut">Definasyon (-500 kcal)</option>
                <option value="bulk">Bulk (+500 kcal)</option>
              </select>
            </div>
          </div>

          <div className="flex flex-1 flex-col gap-3">
            <label htmlFor="ai-diet-prompt" className="sr-only">
              Yapay zekâya talimat
            </label>
            <textarea
              id="ai-diet-prompt"
              {...register('user_prompt')}
              placeholder="Örn: Yulaf ve tavuk yemem alternatif öner. Yağı zeytinyağı + kuruyemiş olarak ayarla..."
              className="min-h-[90px] w-full rounded-xl border bg-white p-3 text-xs outline-none focus:border-brand-purple dark:bg-zinc-900"
            />
            <div className="flex items-center gap-3">
              {targetCalories > 0 && (
                <div
                  role="status"
                  aria-live="polite"
                  className="flex flex-1 items-center justify-center rounded-xl border bg-white p-3 dark:bg-zinc-900"
                >
                  <p className="mr-2 text-[10px] font-bold text-gray-500">HEDEF:</p>
                  <p className="text-xl font-black text-brand-purple">
                    {targetCalories} <span className="text-xs">kcal</span>
                  </p>
                </div>
              )}
              <button
                type="submit"
                disabled={isGenerating}
                aria-busy={isGenerating}
                className="flex-1 rounded-xl bg-brand-purple p-3 text-sm font-bold text-white shadow-md transition-all hover:bg-brand-purpleHover disabled:opacity-50"
              >
                {isGenerating ? 'Hesaplanıyor...' : 'Oluştur ✨'}
              </button>
            </div>
          </div>
        </div>
      </form>

      {/* HIZLI BESİN EKLEME PANELİ (Oto-Tamamlama) */}
      <div className="relative z-10 flex flex-col items-end gap-4 rounded-2xl border border-gray-200 bg-gray-50 p-4 shadow-sm dark:border-zinc-800 dark:bg-zinc-900 md:flex-row">
        <div className="w-full md:w-1/4">
          <label htmlFor="quick-add-day" className="mb-1 block text-[10px] font-bold text-gray-500">
            GÜN SEÇ
          </label>
          <select
            id="quick-add-day"
            value={quickAddDay}
            onChange={(e) => setQuickAddDay(e.target.value as DayName)}
            className="w-full rounded-xl border bg-white p-2.5 text-sm outline-none dark:border-zinc-700 dark:bg-black"
          >
            {DAYS.map((d) => (
              <option key={d} value={d}>
                {d}
              </option>
            ))}
          </select>
        </div>

        <div className="relative w-full md:w-2/4">
          <label
            htmlFor="quick-add-search"
            className="mb-1 block text-[10px] font-bold text-gray-500"
          >
            BESİN ARA
          </label>
          <input
            id="quick-add-search"
            type="text"
            role="combobox"
            aria-expanded={isListOpen}
            aria-controls="quick-add-listbox"
            aria-autocomplete="list"
            aria-activedescendant={activeOption ? `food-option-${activeOption.id}` : undefined}
            placeholder="Örn: Yulaf, Tavuk..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              setSelectedFood(null)
              setActiveIndex(-1)
            }}
            onKeyDown={handleSearchKeyDown}
            className="w-full rounded-xl border bg-white p-2.5 text-sm outline-none focus:border-brand-purple dark:border-zinc-700 dark:bg-black"
          />
          {isListOpen && (
            <div
              id="quick-add-listbox"
              role="listbox"
              aria-label="Besin önerileri"
              className="absolute left-0 top-full z-50 mt-1 w-full overflow-hidden rounded-xl border border-gray-200 bg-white shadow-xl dark:border-zinc-700 dark:bg-zinc-900"
            >
              {suggestions.map((food, index) => (
                <button
                  type="button"
                  key={food.id}
                  id={`food-option-${food.id}`}
                  role="option"
                  aria-selected={index === activeIndex}
                  onClick={() => pickFood(food)}
                  onMouseEnter={() => setActiveIndex(index)}
                  className={`w-full cursor-pointer border-b p-3 text-left text-sm last:border-0 dark:border-zinc-800 ${
                    index === activeIndex ? 'bg-brand-purple/10' : 'hover:bg-brand-purple/10'
                  }`}
                >
                  <span className="font-bold">{food.name}</span>{' '}
                  <span className="text-[10px] text-gray-500">
                    ({food.calories_per_100g} kcal/100g)
                  </span>
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="w-full md:w-1/4">
          <label
            htmlFor="quick-add-grams"
            className="mb-1 block text-[10px] font-bold text-gray-500"
          >
            GRAMAJ
          </label>
          <input
            id="quick-add-grams"
            type="number"
            value={quickAddGrams}
            onChange={(e) => setQuickAddGrams(e.target.value)}
            className="w-full rounded-xl border bg-white p-2.5 text-sm outline-none focus:border-brand-purple dark:border-zinc-700 dark:bg-black"
          />
        </div>

        <button
          type="button"
          onClick={handleQuickAdd}
          className="w-full whitespace-nowrap rounded-xl bg-brand-purple px-6 py-2.5 font-bold text-white shadow-md transition-transform active:scale-95 md:w-auto"
        >
          Hızlı Ekle <span aria-hidden="true">⚡</span>
        </button>
      </div>

      {/* TABLO */}
      <QueryState
        isLoading={planQuery.isLoading || foodsQuery.isLoading}
        isError={planQuery.isError}
        error={planQuery.error}
        skeleton={<SkeletonTable rows={7} cols={3} />}
        onRetry={() => void planQuery.refetch()}
      >
        <div className="overflow-x-auto rounded-xl border border-gray-200 dark:border-zinc-800">
          <table className="w-full text-left text-sm">
            <caption className="sr-only">
              Haftalık beslenme planı: gün, besinler ve otomatik hesaplanan kalori.
            </caption>
            <thead className="border-b border-gray-200 bg-gray-50 dark:border-zinc-800 dark:bg-zinc-900">
              <tr>
                <th scope="col" className="w-1/4 p-3 font-bold text-gray-600 dark:text-gray-300">
                  Gün
                </th>
                <th scope="col" className="p-3 font-bold text-gray-600 dark:text-gray-300">
                  Besinler (Besin:Gramaj)
                </th>
                <th scope="col" className="w-1/6 p-3 font-bold text-gray-600 dark:text-gray-300">
                  Otomatik Kalori
                </th>
              </tr>
            </thead>
            <tbody>
              {DAYS.map((day) => (
                <tr
                  key={day}
                  className="border-b border-gray-100 transition-colors hover:bg-gray-50/50 dark:border-zinc-800/50"
                >
                  <th
                    scope="row"
                    className="p-3 text-left font-bold text-gray-700 dark:text-gray-300"
                  >
                    {day}
                  </th>
                  <td className="p-2">
                    <label htmlFor={`nutrition-${day}`} className="sr-only">
                      {day} besinleri
                    </label>
                    <input
                      id={`nutrition-${day}`}
                      value={nutritionData[day].items}
                      onChange={(e) => handleManualNutritionChange(day, e.target.value)}
                      placeholder="Manuel de yazabilirsiniz..."
                      className="w-full rounded-lg border border-transparent bg-transparent p-2 outline-none transition-all hover:border-gray-200 focus:border-brand-purple dark:hover:border-zinc-700"
                    />
                  </td>
                  <td className="p-3 font-black text-brand-purple">
                    {nutritionData[day].total}{' '}
                    <span className="text-xs font-bold opacity-50">kcal</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </QueryState>

      <button
        type="button"
        onClick={handleSaveProgram}
        disabled={savePlan.isPending}
        aria-busy={savePlan.isPending}
        className="w-full rounded-xl bg-emerald-500 py-4 text-sm font-black text-white shadow-md transition-transform hover:bg-emerald-600 active:scale-95 disabled:opacity-50"
      >
        Beslenme Tablosunu Kaydet
      </button>
    </div>
  )
}

'use client'

// Haftalık antrenman planı: AI üretimi, sürükle-bırak egzersiz kütüphanesi,
// koç onay akışı ve canlı ("gym modu") antrenman takibi.

import { useEffect, useMemo, useState } from 'react'
import type { DragEvent, JSX } from 'react'
import { toast } from 'sonner'

import { QueryState, SkeletonTable } from '@/components/ui'
import {
  useApproveProgram,
  useCoachId,
  useCreateWorkoutLogs,
  useExercises,
  useGenerateWorkout,
  usePendingApprovals,
  useSaveWorkoutPlan,
  useSubmitProgramForApproval,
  useWorkoutLogs,
  useWorkoutPlan,
} from '@/hooks'
import type { SplitType } from '@/lib/api/types'
import { DAYS, formatTime, getTodayName } from '@/lib/utils'
import {
  DAY_NAMES,
  parseWorkoutPlan,
  type DayName,
  type Json,
  type UserRole,
  type WorkoutPlan,
} from '@/types'

export interface WorkoutTabProps {
  targetId: string | undefined
  currentUserId: string | undefined
  userRole: UserRole | null | undefined
  selectedClientIds: string[]
  onDownloadImage: () => void
}

interface LiveExercise {
  name: string
  sets: number
  reps: number
}

interface CompletedSet {
  exercise_name: string
  weight_kg: number
  reps: number
  rpe: number | null
}

function emptyWorkoutPlan(): WorkoutPlan {
  const plan = {} as WorkoutPlan
  for (const day of DAY_NAMES) plan[day] = ''
  return plan
}

/** Tek bir günü değiştirip yeni plan nesnesi döndürür (tip güvenli kopya). */
function withDay(plan: WorkoutPlan, day: DayName, value: string): WorkoutPlan {
  const next: WorkoutPlan = { ...plan }
  next[day] = value
  return next
}

/** `program_approvals.workout_data` Json olarak saklanır; güvenle plana çevirir. */
function jsonToWorkoutPlan(value: Json): WorkoutPlan {
  return parseWorkoutPlan(typeof value === 'string' ? value : JSON.stringify(value))
}

/**
 * "1. Bench Press - 4x8 | notlar" biçimindeki satırları canlı antrenman
 * hareketlerine çevirir. Format bozuksa satır atlanır.
 */
function parseDayPlan(plan: string): LiveExercise[] {
  const result: LiveExercise[] = []

  for (const line of plan.split('\n')) {
    if (!/^\d+\./.test(line) && !line.includes('-')) continue

    const parts = line.split('-')
    if (parts.length < 2) continue

    const rawName = parts[0]
    const rawSetsReps = parts[1]
    if (rawName === undefined || rawSetsReps === undefined) continue

    const name = rawName.replace(/^\d+\.\s*/, '').trim()
    if (!name) continue

    const setsReps = (rawSetsReps.split('|')[0] ?? '').trim().split(/[xX]/)
    const sets = Number.parseInt(setsReps[0] ?? '', 10) || 3
    const reps = Number.parseInt(setsReps[1] ?? '', 10) || 12

    result.push({ name, sets, reps })
  }

  return result
}

export default function WorkoutTab({
  targetId,
  currentUserId,
  userRole,
  selectedClientIds,
  onDownloadImage,
}: WorkoutTabProps): JSX.Element {
  const exercisesQuery = useExercises()
  const planQuery = useWorkoutPlan(targetId)
  const approvalsQuery = usePendingApprovals(targetId)
  const { data: coachId } = useCoachId()

  const savePlan = useSaveWorkoutPlan()
  const submitForApproval = useSubmitProgramForApproval()
  const approveProgram = useApproveProgram()
  const createWorkoutLogs = useCreateWorkoutLogs()
  const generateWorkout = useGenerateWorkout()

  // Canlı antrenman bittiğinde geçmiş setler tazelensin diye önbellek burada tutulur.
  useWorkoutLogs(targetId)

  const exerciseDB = useMemo(() => exercisesQuery.data ?? [], [exercisesQuery.data])
  const pendingApprovals = approvalsQuery.data ?? []
  const firstApproval = pendingApprovals[0]

  const [workoutData, setWorkoutData] = useState<WorkoutPlan>(() => emptyWorkoutPlan())

  // targetId değiştiğinde düzenleme taslağını sunucudan gelen planla tazeler.
  // React'in "prop değişince state ayarlama" kalıbı: render sırasında setState,
  // effect kullanmadan — böylece cascading render oluşmaz ve set-state-in-effect
  // lint hatası ortadan kalkar. Anahtar yalnızca targetId değil, "targetId + planın
  // yüklenmiş olması" — planQuery.data asenkron geldiği için targetId değişir değişmez
  // henüz undefined olabilir; veri gelince taslağı yükleyebilmek için isFetched de anahtara girer.
  // Aynı öğrenci için anahtar sabit kaldığı sürece (ör. arka planda refetch) kullanıcının
  // düzenlemeleri ezilmez.
  const planKey = targetId ? `${targetId}:${planQuery.isFetched ? '1' : '0'}` : 'none'
  const [loadedPlanKey, setLoadedPlanKey] = useState(planKey)
  if (planKey !== loadedPlanKey) {
    setLoadedPlanKey(planKey)
    setWorkoutData(
      targetId && planQuery.isFetched ? (planQuery.data ?? emptyWorkoutPlan()) : emptyWorkoutPlan()
    )
  }

  const isWaitingMyApproval = userRole === 'client' && pendingApprovals.length > 0

  // --- AI antrenör ------------------------------------------------------------
  const [smartSplit, setSmartSplit] = useState('')
  const [aiPrompt, setAiPrompt] = useState('')

  const generateSmartWorkout = async (): Promise<void> => {
    if (!smartSplit) {
      toast.error('Lütfen bir şablon seçin!')
      return
    }

    // TODO: yaş / hedef / kilo öğrencinin profilinden okunmalı (şimdilik sabit).
    const result = await generateWorkout.mutateAsync({
      split_type: smartSplit as SplitType,
      user_prompt: aiPrompt,
      age: 20,
      goal: 'bulk',
      weight: 75,
    })

    const next = emptyWorkoutPlan()
    for (const day of DAY_NAMES) {
      next[day] = result.workout_plan[day] ?? ''
    }
    setWorkoutData(next)
  }

  // --- Onay akışı -------------------------------------------------------------
  const sendToCoachForApproval = (): void => {
    if (!currentUserId) {
      toast.error('Oturum bulunamadı. Lütfen tekrar giriş yapın.')
      return
    }
    const hasContent = DAY_NAMES.some((day) => workoutData[day].trim() !== '')
    if (!hasContent) {
      toast.error('Program boş olamaz!')
      return
    }

    // Bildirim koça gider; koç bulunamazsa onay kaydı yine de oluşturulur.
    submitForApproval.mutate({
      clientId: currentUserId,
      plan: workoutData,
      ...(coachId ? { coachId } : {}),
    })
  }

  const handleApprove = (): void => {
    if (!firstApproval) return
    approveProgram.mutate({
      approvalId: firstApproval.id,
      clientId: firstApproval.client_id,
      plan: jsonToWorkoutPlan(firstApproval.workout_data),
      ...(currentUserId ? { reviewerId: currentUserId } : {}),
    })
  }

  const handleSaveProgram = (): void => {
    const clientIds =
      userRole === 'coach' ? selectedClientIds : currentUserId ? [currentUserId] : []
    if (clientIds.length === 0) {
      toast.error('Öğrenci seçin!')
      return
    }
    savePlan.mutate({ clientIds, plan: workoutData })
  }

  // --- Sürükle-bırak + klavye alternatifi -------------------------------------
  const [dragOverDay, setDragOverDay] = useState<DayName | null>(null)
  const [draggingName, setDraggingName] = useState<string | null>(null)
  const [keyboardTargetDay, setKeyboardTargetDay] = useState<DayName>(() => getTodayName())

  const appendExercise = (day: DayName, exerciseName: string): void => {
    setWorkoutData((prev) => {
      const currentText = prev[day]
      const line = `${exerciseName} - 3x10`
      const newText = currentText.trim() === '' ? line : `${currentText}\n${line}`
      return withDay(prev, day, newText)
    })
  }

  const handleDragStart = (event: DragEvent<HTMLDivElement>, exerciseName: string): void => {
    event.dataTransfer.setData('text/plain', exerciseName)
    setDraggingName(exerciseName)
  }

  const handleDragEnd = (): void => setDraggingName(null)

  const handleDragOver = (event: DragEvent<HTMLTextAreaElement>, day: DayName): void => {
    event.preventDefault()
    setDragOverDay(day)
  }

  const handleDragLeave = (): void => setDragOverDay(null)

  const handleDrop = (event: DragEvent<HTMLTextAreaElement>, day: DayName): void => {
    event.preventDefault()
    setDragOverDay(null)
    setDraggingName(null)

    const exerciseName = event.dataTransfer.getData('text/plain')
    if (exerciseName) appendExercise(day, exerciseName)
  }

  // --- Egzersiz kütüphanesi ---------------------------------------------------
  const [recommenderFilter, setRecommenderFilter] = useState('')

  const filteredExercises = useMemo(() => {
    if (!recommenderFilter) return exerciseDB
    const q = recommenderFilter.toLowerCase()
    return exerciseDB.filter(
      (ex) =>
        ex.name.toLowerCase().includes(q) ||
        ex.body_part?.toLowerCase().includes(q) ||
        ex.target?.toLowerCase().includes(q) ||
        ex.equipment?.toLowerCase().includes(q)
    )
  }, [exerciseDB, recommenderFilter])

  const visibleExercises = filteredExercises.slice(0, 30)

  // --- Canlı antrenman modu ---------------------------------------------------
  const [isLiveWorkout, setIsLiveWorkout] = useState(false)
  const [liveExercises, setLiveExercises] = useState<LiveExercise[]>([])
  const [currentExIdx, setCurrentExIdx] = useState(0)
  const [currentSet, setCurrentSet] = useState(1)
  const [liveWeight, setLiveWeight] = useState('')
  const [liveReps, setLiveReps] = useState('')
  const [restTime, setRestTime] = useState(0)
  const [completedSets, setCompletedSets] = useState<CompletedSet[]>([])
  const [isGifPlaying, setIsGifPlaying] = useState(false)

  useEffect(() => {
    if (restTime <= 0) return
    const timer = setInterval(() => setRestTime((prev) => prev - 1), 1000)
    return () => clearInterval(timer)
  }, [restTime])

  const startLiveWorkout = (): void => {
    const today = getTodayName()
    const todaysPlan = workoutData[today]

    if (!todaysPlan || todaysPlan.toLowerCase().includes('dinlenme') || todaysPlan.trim() === '') {
      toast.error('Bugün dinlenme günün veya atanmış bir antrenman yok! Kaslarını dinlendir.')
      return
    }

    const parsed = parseDayPlan(todaysPlan)
    if (parsed.length === 0) {
      toast.error('Antrenman formatı uygun değil.')
      return
    }

    setLiveExercises(parsed)
    setCurrentExIdx(0)
    setCurrentSet(1)
    setCompletedSets([])
    setLiveWeight('')
    setLiveReps('')
    setRestTime(0)
    setIsLiveWorkout(true)
  }

  const handleCompleteSet = (): void => {
    const ex = liveExercises[currentExIdx]
    if (!ex) return

    if (!liveWeight || !liveReps) {
      toast.error('Lütfen bu set için kilo ve tekrar gir!')
      return
    }

    setCompletedSets((prev) => [
      ...prev,
      {
        exercise_name: ex.name,
        weight_kg: Number.parseFloat(liveWeight),
        reps: Number.parseInt(liveReps, 10),
        rpe: null,
      },
    ])

    if (currentSet < ex.sets) {
      setCurrentSet((prev) => prev + 1)
      setRestTime(90)
    } else if (currentExIdx < liveExercises.length - 1) {
      setCurrentExIdx((prev) => prev + 1)
      setCurrentSet(1)
      setRestTime(120)
      setLiveWeight('')
    } else {
      toast.success('🎉 İNANILMAZ! Bugünün tüm hareketlerini tamamladın!')
      setCurrentExIdx((prev) => prev + 1)
      setRestTime(0)
    }
  }

  const finishLiveWorkout = async (): Promise<void> => {
    if (completedSets.length === 0 || !currentUserId) {
      setIsLiveWorkout(false)
      return
    }
    // Başarı/hata toast'ı hook içinde gösterilir.
    await createWorkoutLogs.mutateAsync({ clientId: currentUserId, sets: completedSets })
    setIsLiveWorkout(false)
  }

  if (isLiveWorkout) {
    const currentExercise = liveExercises[currentExIdx]
    const exDetails = currentExercise
      ? exerciseDB.find((e) => e.name.toLowerCase() === currentExercise.name.toLowerCase())
      : undefined
    const gifSrc = exDetails
      ? isGifPlaying && exDetails.gif_url
        ? exDetails.gif_url
        : (exDetails.image ?? exDetails.gif_url)
      : null

    return (
      <div className="relative mt-4 flex w-full animate-fadeIn flex-col items-center rounded-3xl border border-gray-100 bg-white p-6 shadow-xl dark:border-zinc-800 dark:bg-[#16161d] md:p-10">
        <button
          type="button"
          onClick={() => void finishLiveWorkout()}
          className="absolute right-4 top-4 rounded-lg bg-red-500/10 px-4 py-2 text-xs font-bold text-red-500 hover:bg-red-500/20"
        >
          Bitir
        </button>
        <h3 className="mb-2 text-xl font-black text-brand-purple">
          <span aria-hidden="true">🏋️</span> CANLI GYM MODU
        </h3>
        <p className="mb-6 text-sm font-bold uppercase text-gray-500">
          {getTodayName()} Antrenmanı
        </p>

        {currentExercise ? (
          <div className="w-full max-w-md rounded-3xl border bg-gray-50 p-6 text-center shadow-inner dark:bg-zinc-900">
            {restTime > 0 ? (
              <div className="flex animate-pulse flex-col items-center py-6">
                <p className="mb-2 font-bold text-gray-500">DİNLENME SÜRESİ</p>
                <div
                  role="timer"
                  aria-live="polite"
                  aria-label={`Dinlenme süresi ${formatTime(restTime)}`}
                  className="font-mono text-6xl font-black text-brand-purple"
                >
                  {formatTime(restTime)}
                </div>
                <button
                  type="button"
                  onClick={() => setRestTime(0)}
                  className="mt-4 text-xs text-gray-400 underline"
                >
                  Süreyi Atla
                </button>
              </div>
            ) : (
              <>
                <p className="mb-4 inline-block rounded-full bg-brand-purple/10 px-3 py-1 text-sm font-bold text-brand-purple">
                  Hareket {currentExIdx + 1} / {liveExercises.length}
                </p>

                {/* HOVER OYNATICI */}
                <div
                  className="group relative mb-4 flex h-48 w-full cursor-pointer items-center justify-center overflow-hidden rounded-xl border border-gray-300 bg-zinc-200 dark:border-zinc-800 dark:bg-black"
                  onMouseEnter={() => setIsGifPlaying(true)}
                  onMouseLeave={() => setIsGifPlaying(false)}
                >
                  {gifSrc ? (
                    <>
                      <img
                        src={gifSrc}
                        alt={`${currentExercise.name} hareketinin gösterimi`}
                        loading="lazy"
                        className={`h-full w-full object-cover transition-all duration-300 ${
                          isGifPlaying ? 'scale-105 opacity-100' : 'scale-100 opacity-60 grayscale'
                        }`}
                      />
                      {!isGifPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center">
                          <div className="rounded-full bg-black/60 px-4 py-2 text-xs font-bold text-white backdrop-blur-sm transition-transform group-hover:scale-110">
                            <span aria-hidden="true">▶️</span> Oynatmak için Üzerine Gel
                          </div>
                        </div>
                      )}
                      {exDetails?.equipment ? (
                        <span className="absolute bottom-2 right-2 z-10 rounded-md bg-black/80 px-2 py-1 text-[10px] text-white">
                          {exDetails.equipment}
                        </span>
                      ) : null}
                    </>
                  ) : (
                    <div className="flex flex-col items-center gap-2 text-gray-400">
                      <span className="text-3xl" aria-hidden="true">
                        🎥
                      </span>
                      <span className="text-[10px] font-bold">Görsel Bulunamadı</span>
                    </div>
                  )}
                </div>

                <h2 className="mb-2 text-2xl font-black text-gray-800 dark:text-zinc-100">
                  {currentExercise.name}
                </h2>
                <p className="mb-6 text-lg font-bold text-gray-500">
                  Set {currentSet} / {currentExercise.sets}{' '}
                  <span className="text-brand-purple opacity-50">
                    ({currentExercise.reps} Tekrar)
                  </span>
                </p>

                <p className="sr-only" aria-live="polite">
                  {currentExercise.name}, set {currentSet} / {currentExercise.sets}, hedef{' '}
                  {currentExercise.reps} tekrar.
                </p>

                <div className="mb-6 flex gap-4">
                  <div className="flex-1">
                    <label
                      htmlFor="live-weight"
                      className="mb-1 block text-[10px] font-bold text-gray-400"
                    >
                      KİLO (KG)
                    </label>
                    <input
                      id="live-weight"
                      type="number"
                      value={liveWeight}
                      onChange={(e) => setLiveWeight(e.target.value)}
                      className="w-full rounded-2xl border-2 p-4 text-center text-xl font-black outline-none focus:border-brand-purple dark:bg-black"
                    />
                  </div>
                  <div className="flex-1">
                    <label
                      htmlFor="live-reps"
                      className="mb-1 block text-[10px] font-bold text-gray-400"
                    >
                      TEKRAR
                    </label>
                    <input
                      id="live-reps"
                      type="number"
                      value={liveReps}
                      onChange={(e) => setLiveReps(e.target.value)}
                      placeholder={currentExercise.reps.toString()}
                      className="w-full rounded-2xl border-2 p-4 text-center text-xl font-black outline-none focus:border-brand-purple dark:bg-black"
                    />
                  </div>
                </div>
                <button
                  type="button"
                  onClick={handleCompleteSet}
                  className="w-full rounded-2xl bg-brand-purple py-4 text-lg font-black text-white shadow-lg active:scale-95"
                >
                  {currentSet === currentExercise.sets ? 'Son Seti Tamamla' : 'Seti Tamamla'}
                </button>
              </>
            )}
          </div>
        ) : (
          <div className="py-10 text-center">
            <div className="mb-4 text-6xl" aria-hidden="true">
              🏆
            </div>
            <h2 className="mb-2 text-2xl font-black text-emerald-500">MÜKEMMEL İŞ!</h2>
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="animate-fadeIn space-y-8">
      {userRole === 'coach' && firstApproval ? (
        <div className="rounded-2xl border border-orange-200 bg-orange-50 p-5 shadow-sm dark:bg-orange-900/20">
          <h4 className="mb-2 flex items-center gap-2 font-black text-orange-600">
            <span aria-hidden="true">⚠️</span> ONAY BEKLEYEN PROGRAM VAR
          </h4>
          <p className="mb-4 text-sm text-gray-700 dark:text-gray-300">
            Öğrenci yapay zeka ile tasarladığı bu programı onayına sundu. İncele ve onayla.
          </p>
          <div className="flex gap-3">
            <button
              type="button"
              onClick={() => setWorkoutData(jsonToWorkoutPlan(firstApproval.workout_data))}
              className="rounded-lg border border-orange-200 bg-white px-4 py-2 text-xs font-bold text-orange-600 shadow-sm dark:bg-black"
            >
              <span aria-hidden="true">👀</span> Taslağı Görüntüle
            </button>
            <button
              type="button"
              onClick={handleApprove}
              disabled={approveProgram.isPending}
              aria-busy={approveProgram.isPending}
              className="rounded-lg bg-orange-500 px-4 py-2 text-xs font-black text-white shadow-md hover:bg-orange-600 disabled:opacity-50"
            >
              <span aria-hidden="true">✅</span> Onayla ve Profiline İşle
            </button>
          </div>
        </div>
      ) : null}

      <div className="flex items-center justify-between border-b pb-3 dark:border-zinc-800">
        <h4 className="text-lg font-bold text-gray-800 dark:text-zinc-200">
          Haftalık Antrenman Planı
        </h4>
        <div className="flex gap-2">
          {userRole === 'client' && !isWaitingMyApproval && (
            <button
              type="button"
              onClick={startLiveWorkout}
              className="animate-pulse rounded-lg bg-brand-purple px-4 py-2 text-xs font-black text-white shadow-lg"
            >
              <span aria-hidden="true">🏋️</span> BUGÜNÜ BAŞLAT
            </button>
          )}
          <button
            type="button"
            onClick={onDownloadImage}
            className="rounded-lg bg-brand-purple/10 px-3 py-1.5 text-xs font-bold text-brand-purple"
          >
            <span aria-hidden="true">🖼️</span> Görsel
          </button>
        </div>
      </div>

      {/* isWaitingMyApproval yalnızca userRole === 'client' iken true olabilir (bkz. tanım),
          bu yüzden ek bir 'coach' kontrolü gereksizdir — koç için bu blok zaten görünür. */}
      {!isWaitingMyApproval && (
        <div className="mb-6 flex flex-col items-start gap-4 rounded-2xl border border-blue-500/20 bg-gradient-to-br from-blue-500/10 to-brand-purple/5 p-5 shadow-sm md:flex-row">
          <div className="pt-2 text-4xl" aria-hidden="true">
            🤖
          </div>
          <div className="w-full flex-1 space-y-3">
            <div>
              <label htmlFor="ai-split" className="mb-1 block text-xs font-black text-blue-600">
                AKILLI ANTRENÖR (AI)
              </label>
              <select
                id="ai-split"
                value={smartSplit}
                onChange={(e) => setSmartSplit(e.target.value)}
                className="w-full rounded-xl border bg-white p-3 text-sm font-bold outline-none dark:bg-zinc-900"
              >
                <option value="">Şablon Seçin...</option>
                <option value="ppl_torso_limbs">PPL + Torso + Limbs (5 Günlük)</option>
                <option value="ppl">Push / Pull / Legs (3 Günlük)</option>
                <option value="upper_lower">Upper / Lower (4 Günlük)</option>
              </select>
            </div>
            <div>
              <label
                htmlFor="ai-workout-prompt"
